<?php
function pdata($n){static $cache=[];if(!isset($cache[$n]))$cache[$n]=json_data($n);return $cache[$n];}
function plook($key,$v){$map=['province_id'=>'provinces','district_id'=>'districts','sector_id'=>'sectors','cell_id'=>'cells','village_id'=>'villages','facility_id'=>'facilities','chw_id'=>'chws','user_id'=>'users'];if(!isset($map[$key]))return $v;$x=array_values(array_filter(pdata($map[$key]),fn($a)=>($a['id']??null)===$v));if(!$x)return $v;return $x[0]['name']??trim(($x[0]['first_name']??'').' '.($x[0]['last_name']??''));}
function pstatus($v){$cls=strtolower(str_replace(['_',' '],'-',(string)$v));return '<span class="badge '.htmlspecialchars($cls).'">'.htmlspecialchars(str_replace('_',' ',$v)).'</span>';}
function ptable($rows,$cols){if(!$rows){return '<div class="empty">No records found.</div>';}echo '<div class="table-wrap"><table><thead><tr>';foreach($cols as $c)echo '<th>'.htmlspecialchars(str_replace('_',' ',$c)).'</th>';echo '</tr></thead><tbody>';foreach($rows as $r){echo '<tr>';foreach($cols as $c){$v=$r[$c]??'';if(in_array($c,['status','urgency']))$out=pstatus($v);else $out=htmlspecialchars((string)plook($c,$v),ENT_QUOTES,'UTF-8');echo '<td>'.$out.'</td>';}echo '</tr>';}echo '</tbody></table></div>';}
